#!/usr/bin/env bash
set -euo pipefail

tmpdir="$(mktemp -d)"
cat > "$tmpdir/SyncBytecodeDemo.java" <<'JAVA'
public class SyncBytecodeDemo {
    private final Object lock = new Object();

    // 同步实例方法：ACC_SYNCHRONIZED，锁 this
    public synchronized int method(int x) {
        return nested(x) + 1;
    }

    // 可重入：同一线程再次获取同一把锁
    private synchronized int nested(int x) {
        return x + 1;
    }

    // 同步代码块：monitorenter/monitorexit
    public int block() {
        synchronized (lock) {
            return 42;
        }
    }

    // 静态同步方法：锁 Class 对象
    public static synchronized int staticMethod() {
        return 7;
    }

    public static void main(String[] args) throws Exception {
        SyncBytecodeDemo demo = new SyncBytecodeDemo();
        System.out.println("method=" + demo.method(1));
        System.out.println("block=" + demo.block() + ", static=" + staticMethod());

        // wait/notify 验证：wait 必须持有 monitor，条件检查用 while
        Object monitor = new Object();
        boolean[] ready = {false};
        Thread waiter = new Thread(() -> {
            synchronized (monitor) {
                while (!ready[0]) {
                    try {
                        monitor.wait();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
                System.out.println("waiter observed ready");
            }
        }, "waiter");
        waiter.start();
        Thread.sleep(100);
        synchronized (monitor) {
            ready[0] = true;
            monitor.notifyAll();
        }
        waiter.join();
        System.out.println("all demos passed");
    }
}
JAVA

javac "$tmpdir/SyncBytecodeDemo.java"

# 查看字节码中的 ACC_SYNCHRONIZED 和 monitorenter/monitorexit
echo "=== Bytecode markers ==="
javap -classpath "$tmpdir" -c -v SyncBytecodeDemo \
  | grep -E 'ACC_SYNCHRONIZED|monitorenter|monitorexit'

# 运行验证可重入和 wait/notify
echo "=== Runtime output ==="
java -cp "$tmpdir" SyncBytecodeDemo
